From 8c9a872b06056ec15ed01dd8707fc21150a2a643 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:34:34 +0100
Subject: [PATCH] applets/showActivityManager: switch activities with the mouse
 wheel

Scrolling over the Activity Switcher widget did nothing. Now each wheel
step switches to the next or previous activity in alphabetical order,
like the Activity Bar, wrapping around at the ends of the list.

BUG: 506284
---
 applets/showActivityManager/qml/main.qml | 63 ++++++++++++++++++++++++
 1 file changed, 63 insertions(+)

diff --git a/applets/showActivityManager/qml/main.qml b/applets/showActivityManager/qml/main.qml
index efb76fe880..df4d8c599f 100644
--- a/applets/showActivityManager/qml/main.qml
+++ b/applets/showActivityManager/qml/main.qml
@@ -32,6 +32,53 @@ PlasmoidItem {
     Plasmoid.onActivated: ActivitySwitcher.Backend.toggleActivityManager()
     preferredRepresentation: fullRepresentation

+    function switchActivity(steps: int): void {
+        let from = -1;
+        for (let i = 0; i < activities.count; ++i) {
+            const activity = activities.objectAt(i);
+            if (switchTimer.running ? activity.id === switchTimer.target : activity.current) {
+                from = i;
+                break;
+            }
+        }
+        if (steps === 0 || from < 0) {
+            return;
+        }
+        switchTimer.target = activities.objectAt(((from + steps) % activities.count + activities.count) % activities.count).id;
+        if (switchTimer.running) {
+            switchTimer.pending = true;
+        } else {
+            switchTimer.pending = false;
+            ActivitySwitcher.Backend.setCurrentActivity(switchTimer.target);
+            switchTimer.start();
+        }
+    }
+
+    Instantiator {
+        id: activities
+        model: Activities.ActivityModel {}
+        delegate: QtObject {
+            required property string id
+            required property bool current
+        }
+    }
+
+    Timer {
+        id: switchTimer
+
+        property string target
+        property bool pending
+
+        interval: 300
+        onTriggered: {
+            if (pending) {
+                pending = false;
+                ActivitySwitcher.Backend.setCurrentActivity(target);
+                start();
+            }
+        }
+    }
+
     DND.DropArea {
         id: dropArea
         anchors.fill: parent
@@ -68,6 +115,22 @@ PlasmoidItem {
             Accessible.role: Accessible.Button

             onClicked: Plasmoid.activated()
+
+            property int wheelDelta: 0
+
+            onWheel: wheel => {
+                wheelDelta += (wheel.inverted ? -1 : 1) * (wheel.angleDelta.y ? wheel.angleDelta.y : wheel.angleDelta.x);
+                let steps = 0;
+                while (wheelDelta >= 120) {
+                    wheelDelta -= 120;
+                    steps--;
+                }
+                while (wheelDelta <= -120) {
+                    wheelDelta += 120;
+                    steps++;
+                }
+                root.switchActivity(steps);
+            }
         }

         PlasmaCore.ToolTipArea {
-- 
